#!/bin/bash
# Print the three most frequent IP addresses in access.log, one per line,
# most frequent first; ties broken by first appearance in the log.
set -eu

LOG="access.log"

awk '
{
    ip = $1
    if (ip == "") next
    count[ip]++
    if (!(ip in first_seen)) {
        order[++n] = ip
        first_seen[ip] = 1
    }
}
END {
    for (i = 1; i <= n; i++) {
        ip = order[i]
        key = sprintf("%020d %020d", count[ip], i)
        print key, ip
    }
}
' "$LOG" | sort | head -n 3 | awk '{print $2}'

#!/bin/bash
# Print the three most frequent IP addresses in access.log, one per line,
# most frequent first; ties broken by first appearance in the log.
set -eu

LOG="access.log"

awk '
{
    ip = $1
    if (ip == "") next
    count[ip]++
    if (!(ip in first_seen)) {
        order[++n] = ip
        first_seen[ip] = 1
    }
}
END {
    for (i = 1; i <= n; i++) {
        ip = order[i]
        print sprintf("%020d %020d", count[ip], i), ip
    }
}
' "$LOG" | sort -k1,1nr -k2,2n | head -n 3 | awk '{print $3}'
